    adcs_vec3_t diff = adcs_vec3_sub(&curr_n, &prev_n);
    adcs_vec3_t rate = adcs_vec3_scale(&diff, 1.0 / dt);
    pg_state.previous = curr_n;
    pg_state.rejects = 0U;
    pg_output.mode = PG_RUN;
    pg_output.rejects = 0U;
    pg_output.cosine = cosine;
    pg_output.rate_t_s = rate;
    pg_output.rate_norm_t_s = adcs_vec3_norm(&rate);
    pg_output.accepted_field_t = curr_n;
    return;
}

rejects = pg_state.rejects + 1U;
if (rejects >= pg_config.max_rejects) {
    pg_state.rejects = rejects;
    pg_output.mode = PG_FAULT;
    pg_output.rejects = rejects;
    pg_output.cosine = cosine;
    pg_output.rate_t_s = zero_v;
    pg_output.rate_norm_t_s = 0.0;
    pg_output.accepted_field_t = pg_state.previous;
    return;
}

pg_state.rejects = rejects;
pg_output.mode = PG_REJECT;
pg_output.rejects = rejects;
pg_output.cosine = cosine;
pg_output.rate_t_s = zero_v;
pg_output.rate_norm_t_s = 0.0;
pg_output.accepted_field_t = pg_state.previous;
return;

